        /// The ID of the runtime to use for the check. If not set, the account's default runtime is used. The runtime must support multi-step checks.
        /// </summary>
        [Input("runtimeId")]
        public Input<string>? RuntimeId { get; set; }

        /// <summary>
        /// A valid piece of Node.js JavaScript code describing a multi-step interaction with the Playwright framework.
        /// </summary>
        [Input("script")]
        public Input<string>? Script { get; set; }

        /// <summary>
        /// The path of the check's script file when using editor-style multi-file scripts (e.g. `entrypoint.spec.ts`).
        /// </summary>
        [Input("scriptPath")]
        public Input<string>? ScriptPath { get; set; }

        [Input("tags")]
        private InputList<string>? _tags;

        /// <summary>
        /// Tags for organizing and filtering checks and monitors.
        /// </summary>
        public InputList<string> Tags
        {
            get => _tags ?? (_tags = new InputList<string>());
            set => _tags = value;
        }

        /// <summary>
        /// Create and resolve an incident based on the alert configuration. Useful for status page automation.
        /// </summary>
        [Input("triggerIncident")]
        public Input<Inputs.MultistepCheckTriggerIncidentGetArgs>? TriggerIncident { get; set; }

        /// <summary>
        /// When true, the account level alert settings are used instead of the `AlertSettings` of this check. Defaults to `True` when `AlertSettings` is not set, and to `False` when it is.
        /// </summary>
        [Input("useGlobalAlertSettings")]
        public Input<bool>? UseGlobalAlertSettings { get; set; }

        public MultistepCheckState()
        {
        }
        public static new MultistepCheckState Empty => new MultistepCheckState();
    }
}
